+        constant.collation = CollationSeq::Unset;
+        constant.nullable = false;
+        let Relation::Membership { right, .. } = &mut plan.root else {
+            unreachable!()
+        };
+        let Relation::Project { input, outputs } = right.as_mut() else {
+            unreachable!()
+        };
